import { Pie } from "react-chartjs-2";
import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
  Legend
} from "chart.js";

ChartJS.register(ArcElement, Tooltip, Legend);

export default function UsagePieChart({ data = [] }) {
  if (!Array.isArray(data) || data.length === 0) {
    return <p>No usage data available</p>;
  }

  const totalProductive = data.reduce(
    (sum, d) => sum + (d.productiveTime || 0),
    0
  );

  const totalUnproductive = data.reduce(
    (sum, d) => sum + (d.unproductiveTime || 0),
    0
  );

  return (
    <Pie
      data={{
        labels: ["Productive", "Unproductive"],
        datasets: [
          {
            data: [totalProductive, totalUnproductive],
            backgroundColor: ["#22c55e", "#ef4444"]
          }
        ]
      }}
      options={{
        plugins: {
          legend: {
            position: "bottom"
          }
        }
      }}
    />
  );
}
